// Centralized configuration & secrets (hardcoded per request)
const CONFIG = {
  pdfMonkey: {
    token: '2zpxHdmsse2ECXgVVtVR',
    templateId: '5539DDB4-EC78-4AE9-A3FB-DB1E7F8DD172' // interior template (pages_html)
  },
  lulu: {
    apiBase: 'https://api.lulu.com',        // set sandbox base if needed
    basicAuth: 'Basic OWIzODhhYWEtZjBjOS00NDhkLWIzZDEtODU2MWE4Y2YyMDk0OjNmc1laN0diYlh2ZFFoc09TeHN0eklicWRiZEpNTXRT'
  },
