// Validate & normalize W4 intake payload + attach CONFIG
// Input sources: Webhook (payload) + Config (W4)

// Utility to collect latest item from a named node (if present), else use current
function latestFrom(nodeName) {
  try {
    const items = $items(nodeName, 0, $runIndex);
    if (items && items.length) return items[0].json;
  } catch {}
  return null;
}

const cfg = latestFrom('Config (W4)')?.CONFIG || ($json.CONFIG || {});
const body = latestFrom('Webhook (W4 Intake)') || $json || {};

// Expected fields from W3 → W4
const orderId = body.orderId || body.amazonOrderId || body.AmazonOrderId;
const pageImageUrls = Array.isArray(body.pageImageUrls) ? body.pageImageUrls : [];
const coverPdfR2Key = body.coverPdfR2Key || null;
const coverPdfUrl   = body.coverPdfUrl || null;

// Optional context
const shippingAddress = body.shippingAddress || body.shipping_address || {};
const customer = body.customer || { email: body.customer_email, name: body.customer_name };
const title = body.title || 'Little Hero Book';

if (!orderId) throw new Error('Missing orderId from W3 → W4');
if (pageImageUrls.length === 0) throw new Error('pageImageUrls[] is required and cannot be empty');
if (!(coverPdfR2Key || coverPdfUrl)) throw new Error('coverPdfR2Key or coverPdfUrl must be provided');

// Interior PDF filename/key
const pdfFilename = `interior_${orderId}.pdf`;
const pdfR2Key = `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`;

return [{
  json: {
    CONFIG: cfg,
    orderId,
    pageImageUrls,
    coverPdfR2Key,
    coverPdfUrl,
    shippingAddress,
    customer,
    title,
    pdfFilename,
    pdfR2Key
  }
}];

const j = $input.first().json || {};
console.log('W4 Intake Ack →', {
  orderId: j.orderId,
  pages: j.pageImageUrls?.length || 0,
  coverSource: j.coverPdfR2Key ? 'R2 key' : (j.coverPdfUrl ? 'URL' : 'missing')
});
return [{ json: j }];

// Build pages_html for PDFMonkey at 8.75×8.75 in (bleed) from pageImageUrls
const j = $input.first().json || {};
const pages = Array.isArray(j.pageImageUrls) ? j.pageImageUrls : [];
if (pages.length === 0) throw new Error('No pageImageUrls to build pages_html');

const css = `
  <style>
    @page { size: 8.75in 8.75in; margin: 0; }
    html, body { margin:0; padding:0; }
    .page { width:8.75in; height:8.75in; page-break-after: always; }
    .bg { width:100%; height:100%; object-fit: cover; display:block; }
  </style>
`;

const pagesHtml = pages.map(url => {
  return `<section class="page"><img class="bg" src="${url}" alt="" /></section>`;
}).join('\n');

return [{
  json: {
    ...j,
    pages_html: `${css}\n${pagesHtml}`
  }
}];

const d = $input.first().json;
const tpl = d.CONFIG?.pdfMonkey?.templateId;
if (!tpl || tpl === 'REPLACE_WITH_PDFMONKEY_TEMPLATE_ID') {
  throw new Error('Missing PDFMonkey templateId in Config (W4). Please set CONFIG.pdfMonkey.templateId');
}
return [{
  json: {
    ...d,
    document: {
      document_template_id: tpl,
      status: 'pending',
      meta: { _filename: d.pdfFilename },
      payload: { pages_html: d.pages_html }
    }
  }
}];

const createResp = $input.first().json;
const doc = createResp.data || createResp.document || createResp;
const docId = doc.id || doc.data?.id;
if (!docId) throw new Error('PDFMonkey create response missing id');

const http = this.helpers.httpRequest;
const token = ($json.CONFIG && $json.CONFIG.pdfMonkey && $json.CONFIG.pdfMonkey.token) || '2zpxHdmsse2ECXgVVtVR';
const AUTH_HEADER = { Authorization: `Bearer ${token}` };

let status = doc.status || 'queued';
let downloadUrl = doc.download_url || null;
let attempts = 0;
async function sleep(ms){ return new Promise(r=>setTimeout(r, ms)); }

while (attempts < 15) {
  if (status === 'success' && downloadUrl) break;
  const resp = await http({ method:'GET', url:`https://api.pdfmonkey.io/api/v1/documents/${docId}`, json:true, headers: AUTH_HEADER });
  const d = resp.data || resp.document || resp;
  status = d.status;
  downloadUrl = d.download_url || d.file_url || null;
  if (status === 'success' && downloadUrl) break;
  attempts++; await sleep(2000);
}
if (status !== 'success' || !downloadUrl) throw new Error(`PDF not ready (status=${status})`);

const orderId = $json.orderId;
const pdfFilename = $json.pdfFilename || `interior_${orderId}.pdf`;
const pdfR2Key = `book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`;
return [{ json: { ...$json, pdfMonkeyDocumentId: docId, pdfDownloadUrl: downloadUrl, pdfR2Key } }];

/**
 * Prepare PDF Metadata for downstream (no binary)
 */
const input = $input.first().json;
const { orderId, pdfFilename, pdfR2Key } = input;
if (!orderId || !pdfFilename || !pdfR2Key) {
  throw new Error('Missing required PDF metadata: orderId, pdfFilename, or pdfR2Key');
}
console.log(`✓ PDF uploaded to R2: ${pdfR2Key}`);
return [{ json: { ...input, pdfComplete: true, pdfUploadedAt: new Date().toISOString() } }];

const crypto = require('crypto');
const j = $input.first().json || {};
const cfg = j.CONFIG || {};
const { bucket, endpointHost, region, accessKeyId, secretAccessKey } = cfg.r2 || {};
if (!bucket || !endpointHost || !accessKeyId || !secretAccessKey) {
  throw new Error('R2 config incomplete: bucket/endpointHost/accessKeyId/secretAccessKey required');
}
const now = new Date();
const amzDate = now.toISOString().replace(/[-:]/g, '').replace(/\..+/, '') + 'Z';
const date = amzDate.slice(0, 8);
const service = 's3';
const rgn = region || 'auto';
function hmac(key, data){ return require('crypto').createHmac('sha256', key).update(data).digest(); }
function sha256Hex(data){ return require('crypto').createHash('sha256').update(data).digest('hex'); }
function toHex(buffer){ return buffer.toString('hex'); }
function presign(key, expires=3600){
  const host = endpointHost;
  const objectKey = encodeURIComponent(key).replace(/%2F/g,'/');
  const method = 'GET';
  const canonicalUri = `/${bucket}/${objectKey}`;
  const credentialScope = `${date}/${rgn}/${service}/aws4_request`;
  const credential = `${accessKeyId}/${credentialScope}`;
  const signedHeaders = 'host';
  const q = new URLSearchParams({
    'X-Amz-Algorithm': 'AWS4-HMAC-SHA256',
    'X-Amz-Credential': credential,
    'X-Amz-Date': amzDate,
    'X-Amz-Expires': String(expires),
    'X-Amz-SignedHeaders': signedHeaders,
  });
  const canonicalQueryString = q.toString();
  const canonicalHeaders = `host:${host}\n`;
  const payloadHash = 'UNSIGNED-PAYLOAD';
  const canonicalRequest = [method, canonicalUri, canonicalQueryString, canonicalHeaders, signedHeaders, payloadHash].join('\n');
  const stringToSign = ['AWS4-HMAC-SHA256', amzDate, credentialScope, sha256Hex(canonicalRequest)].join('\n');
  const kDate = hmac(Buffer.from('AWS4'+secretAccessKey, 'utf8'), date);
  const kRegion = hmac(kDate, rgn);
  const kService = hmac(kRegion, service);
  const kSigning = hmac(kService, 'aws4_request');
  const signature = toHex(hmac(kSigning, stringToSign));
  const url = `https://${host}/${bucket}/${objectKey}?${canonicalQueryString}&X-Amz-Signature=${signature}`;
  return url;
}
const interiorKey = j.pdfR2Key || j.bookPdfUrl;
const coverKey = j.coverPdfR2Key || j.coverPdfUrl;
if (!interiorKey || !coverKey) throw new Error('Missing R2 keys for interior or cover');
const interiorSignedUrl = presign(interiorKey, 3600);
const coverSignedUrl = presign(coverKey, 3600);
return [{ json: { ...j, interiorSignedUrl, coverSignedUrl } }];

const j = $input.first().json || {};
const dflt = j.CONFIG.defaults || {};
const qty = j.printOptions?.quantity || dflt.quantity || 1;
const shippingLevel = j.printOptions?.shippingLevel || dflt.shippingLevel || 'STANDARD';
const productConfig = {
  trim_size: `${dflt.trimIn.w}x${dflt.trimIn.h}`,
  interior_color: j.printOptions?.color || dflt.print.color,
  interior_paper: j.printOptions?.stock || dflt.print.stock,
  binding: j.printOptions?.binding || dflt.print.binding,
  cover_finish: j.printOptions?.coverFinish || dflt.print.coverFinish
};
const files = { interior: j.interiorSignedUrl, cover: j.coverSignedUrl };
const shippingAddress = j.shippingAddress || {};
const payload = {
  quantity: qty,
  shipping_level: shippingLevel,
  contact_email: j.customer?.email || 'orders@littleherolabs.com',
  address: shippingAddress,
  line_items: [ { title: j.title || 'Little Hero Book', print_options: productConfig, files } ]
};
return [{ json: { ...j, luluPayload: payload } }];

const r = $input.first().json || {};
const jobId = r.id || r.job_id || r.data?.id;
const status = r.status || r.data?.status || 'CREATED';
const cost = r.cost || r.data?.cost || null;
const eta = r.estimated_ship_date || r.data?.estimated_ship_date || null;
return [{ json: { ...$json, luluJobId: jobId, luluStatus: status, luluCost: cost, estimatedShipDate: eta } }];

const j = $input.first().json || {};
const manifest = {
  schema: 'lhb.run-manifest@v2.0',
  stage: '4-print-fulfillment',
  createdAt: new Date().toISOString(),
  orderId: j.orderId,
  artifacts: {
    interiorPdfR2Key: j.pdfR2Key || j.bookPdfUrl,
    coverPdfR2Key: j.coverPdfR2Key
  },
  lulu: {
    jobId: j.luluJobId,
    status: j.luluStatus,
    cost: j.luluCost,
    estimatedShipDate: j.estimatedShipDate
  }
};
const key = `book-mvp-simple-adventure/orders/${j.orderId}/manifests/4-manifest.json`;
return [{ json: { ...j, manifestKey: key, _manifest: manifest } }];
